{"rules": [
  {
    "category": "rent_increase_limit",
    "title": "Annual Allowable Rent Increase",
    "requirement": "Landlords who have reported required information may impose an annual rent increase on tenants in occupancy of no more than 60% of the CPI increase, capped at 7%.",
    "requirement_es": "Los arrendadores que hayan reportado la información requerida pueden aplicar un aumento anual de la renta a los inquilinos en ocupación de no más del 60% del incremento del IPC, con un tope máximo del 7%.",
    "key_value": {"label": "annual cap", "value": "60% of CPI, max 7%"},
    "coverage_conditions": {
      "type": "AND",
      "clauses": [
        {"field": "certificate_of_occupancy_date", "operator": "<=", "value": "1979-06-13", "note": "units newly constructed after June 13, 1979 are generally exempt under 37.3(g)(1)"}
      ]
    },
    "exemptions": [
      {
        "description": "Newly constructed dwelling units that first received a certificate of occupancy after June 13, 1979, subject to certain exceptions.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "certificate_of_occupancy_date", "operator": ">", "value": "1979-06-13"}
          ]
        }
      },
      {
        "description": "Units certified by the Rent Board as having undergone substantial rehabilitation.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "owner_type", "operator": "==", "value": "__unknowable__"}
          ]
        }
      },
      {
        "description": "Hotels, motels, inns, tourist houses, rooming and boarding houses occupied for less than 32 continuous days.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "tenancy_length_months", "operator": "<", "value": 1}
          ]
        }
      },
      {
        "description": "Dwelling units in non-profit cooperatives owned, occupied and controlled by a majority of residents, or non-profit public benefit corporations meeting specific board requirements.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "owner_type", "operator": "==", "value": "nonprofit"}
          ]
        }
      },
      {
        "description": "Housing in licensed hospitals, convents, monasteries, extended care facilities, residential care facilities, or school dormitories.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "property_type", "operator": "==", "value": "other"}
          ]
        }
      },
      {
        "description": "Units whose rents are controlled or regulated by any government unit, agency, or authority, subject to limited exceptions.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "rent_subsidized", "operator": "==", "value": true}
          ]
        }
      },
      {
        "description": "Separately alienable parcels (such as single-family homes or qualifying condominiums) exempt under Costa-Hawkins.",
        "conditions": {
          "type": "OR",
          "clauses": [
            {"field": "property_type", "operator": "==", "value": "single_family"},
            {"field": "property_type", "operator": "==", "value": "condominium"}
          ]
        }
      }
    ],
    "effective_date": null,
    "superseded_date": null,
    "status": "enacted",
    "precedence": {
      "relationship": "stacks_with",
      "target_scope": "none",
      "source_language": null
    },
    "penalty": "Any rent increase which does not conform with the provisions of this section shall be null and void.",
    "source_citation": "S.F. Admin. Code § 37.3(a)(1)",
    "quote": {
      "chunk": "c447",
      "start_words": "A landlord who has reported the required",
      "end_words": "greater than 7%."
    },
    "confidence": 0.95
  },
  {
    "category": "rent_increase_limit",
    "title": "Capital Improvement Rent Increase Limitation for Seismic Strengthening",
    "requirement": "Where a landlord performs seismic strengthening under Building Code Chapters 16B and 16C, certified rent increases for capital improvements cannot exceed 10% of the tenant's base rent in any 12-month period.",
    "requirement_es": "Cuando el arrendador realice obras de refuerzo sísmico conforme a los Capítulos 16B y 16C del Código de Edificación, los aumentos de renta certificados por mejoras de capital no podrán exceder el 10% de la renta base del inquilino en ningún período de 12 meses.",
    "key_value": {"label": "annual cap for seismic capital improvements", "value": "10%"},
    "coverage_conditions": {
      "type": "AND",
      "clauses": [
        {"field": "certificate_of_occupancy_date", "operator": "<=", "value": "1979-06-13", "note": "covered rental units under Chapter 37"}
      ]
    },
    "exemptions": [],
    "effective_date": null,
