  {
    "category": "rent_increase_limit",
    "title": "Rent Increase Limit for Lead Remediation and Abatement",
    "requirement": "Rent increases authorized for costs incurred to remediate lead hazards cannot exceed 10% in any 12-month period across operating/maintenance expenses and capital improvements.",
    "requirement_es": "Los aumentos de renta autorizados para recuperar los costos de remediación de riesgos de plomo no pueden superar el 10% en ningún período de 12 meses sumando gastos operativos/mantenimiento y mejoras de capital.",
    "key_value": {"label": "annual cap for lead remediation", "value": "10%"},
    "coverage_conditions": {
      "type": "AND",
      "clauses": [
        {"field": "certificate_of_occupancy_date", "operator": "<=", "value": "1979-06-13", "note": "covered rental units under Chapter 37"}
      ]
    },
    "exemptions": [],
