  {
    "category": "rent_increase_limit",
    "title": "Prohibition on Rent Increases for Additional Occupants",
    "requirement": "Landlords cannot increase rent solely because a tenant adds an additional occupant, such as a newborn child or family member, even if the lease agreement permits such an increase.",
    "requirement_es": "Los arrendadores no pueden aumentar la renta únicamente porque un inquilino incorpore a un ocupante adicional, tal como un hijo recién nacido o un familiar, aun cuando el contrato de arrendamiento lo permita.",
    "key_value": null,
    "coverage_conditions": {
      "type": "AND",
      "clauses": [
        {"field": "certificate_of_occupancy_date", "operator": "<=", "value": "1979-06-13", "note": "covered rental units under Chapter 37"}
      ]
    },
    "exemptions": [
      {
        "description": "Increases permitted by Costa-Hawkins or petition under 37.3(a)(8) for costs associated with authorized occupants under Section 37.9(a)(2)(C).",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "owner_type", "operator": "==", "value": "__unknowable__"}
          ]
        }
      }
    ],
    "effective_date": null,
    "superseded_date": null,
    "status": "enacted",
    "precedence": {
      "relationship": "yields_to",
      "target_scope": "state",
      "source_language": "Rent increases otherwise permitted by the Costa-Hawkins Rental Housing Act, California Civil Code Section 1950 et seq. (as it may be amended from time to time) are not prohibited or limited by this Section 37.3(a)(11)."
    },
    "penalty": "Any rent increase which does not conform with the provisions of this section shall be null and void.",
    "source_citation": "S.F. Admin. Code § 37.3(a)(11)(A)",
    "quote": {
      "chunk": "c663",
      "start_words": "Except as provided in Section 37.3(a)(11)(B), a",
      "end_words": "rent increase for additional occupants."
    },
    "confidence": 0.95
  },
  {
    "category": "rent_increase_limit",
    "title": "Initial Rent Limitation for Subtenants",
    "requirement": "A tenant subleasing their rental unit cannot charge an incoming subtenant more rent at initial occupancy than what the prime tenant pays the landlord.",
    "requirement_es": "Un inquilino que subarriende su unidad no puede cobrar al subinquilino inicial más renta de la que el inquilino principal paga actualmente al arrendador.",
    "key_value": {"label": "subtenant initial rent cap", "value": "100% of tenant's current rent"},
    "coverage_conditions": {
      "type": "ALWAYS",
      "clauses": []
    },
    "exemptions": [],
