  {
    "category": "rent_increase_limit",
    "title": "Vacancy Control Following Certain Evictions or Termination of Rent Restriction Agreements",
    "requirement": "If a tenancy is terminated via specified no-fault eviction notices, a change in terms under Civil Code § 827, or termination/nonrenewal of an affordable housing agreement, initial base rent for any new tenancy within 5 years cannot exceed the prior lawful rent plus allowable annual increases.",
    "requirement_es": "Si un arrendamiento finaliza mediante ciertos desalojos sin culpa, un cambio en los términos bajo el Código Civil § 827, o la rescisión de un acuerdo de limitación de renta, la renta inicial para un nuevo inquilino dentro de los 5 años siguientes no podrá ser superior a la renta legal anterior más los aumentos anuales permitidos.",
    "key_value": {"label": "vacancy control limit", "value": "prior lawful rent + annual increases"},
    "coverage_conditions": {
      "type": "ALWAYS",
      "clauses": []
    },
    "exemptions": [
      {
        "description": "Initial rent for a unit terminated under Section 37.9(a)(9) set by a subsequent bona fide purchaser for value of the condominium.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {"field": "property_type", "operator": "==", "value": "condominium"}
          ]
        }
      }
    ],
    "effective_date": null,
