  {
    "category": "rent_increase_limit",
    "title": "Pre-November 14, 2002 Capital Improvement Passthrough Cap",
    "requirement": "For capital improvement applications filed before November 14, 2002, certified cost passthroughs cannot exceed 10% of base rent or $30.00 in a twelve-month period, whichever is greater.",
    "requirement_es": "Para las solicitudes de mejoras de capital presentadas antes del 14 de noviembre de 2002, el traspaso del costo certificado no puede exceder el 10% de la renta base o $30.00 en un período de doce meses, lo que sea mayor.",
    "key_value": {"label": "capital improvement passthrough cap (pre-11/14/2002 applications)", "value": "10% or $30.00, whichever is greater"},
    "coverage_conditions": {
      "type": "AND",
      "clauses": [
        {"field": "certificate_of_occupancy_date", "operator": "<=", "value": "1979-06-13", "note": "covered rental units under Chapter 37"}
      ]
